import{_ as a,a as l}from"./chunks/btc_20210819234154.C9myFeCv.js";import{_ as e,o as t,c as i,a0 as r}from"./chunks/framework.DqMqoJl9.js";const s="/assets/btc_20210818163326.DX1o_ydZ.png",n="/assets/btc_20210818175301.AYybzOe9.png",p="/assets/btc_20210818181656.CK9stSku.png",c="/assets/btc_20210818181709.COCQqP8j.png",h="/assets/btc_20210819101059.BtVs4Tfv.png",f=JSON.parse('{"title":"比特币","description":"","frontmatter":{},"headers":[],"relativePath":"blockChain/4-btc.md","filePath":"blockChain/4-btc.md","lastUpdated":1791573371000}'),d={name:"blockChain/4-btc.md"};function g(u,o,b,k,_,P){return t(),i("div",null,[...o[0]||(o[0]=[r('<h1 id="比特币" tabindex="-1">比特币 <a class="header-anchor" href="#比特币" aria-label="Permalink to &quot;比特币&quot;">​</a></h1><h2 id="_1-比特币概念" tabindex="-1">1 比特币概念 <a class="header-anchor" href="#_1-比特币概念" aria-label="Permalink to &quot;1 比特币概念&quot;">​</a></h2><h3 id="_1-1-比特币的特性" tabindex="-1">1.1 比特币的特性 <a class="header-anchor" href="#_1-1-比特币的特性" aria-label="Permalink to &quot;1.1 比特币的特性&quot;">​</a></h3><ol><li><strong>去中心化</strong>。这意味着没有中心的服务器，不受某个人的控制，整个系统直接由用户端的电脑构成。这样的技术难度是非常大的，并不像手机 App 或是小网站一样，你想发布就发布，这需要有人来跟你一起玩</li><li><strong>数据防篡改</strong>。所有交易记录全量保存，并公开给所有的人，而且还被加密和校验。并不是数据不能被篡改，而是数据被篡改的成本非常大</li><li><strong>固定的发行量</strong>。不会像国家中央银行那样乱印钞票，造成通货膨胀</li></ol><h3 id="_1-2-去中心化交易流程" tabindex="-1">1.2 去中心化交易流程 <a class="header-anchor" href="#_1-2-去中心化交易流程" aria-label="Permalink to &quot;1.2 去中心化交易流程&quot;">​</a></h3><ol><li>首先，需要交易的用户把交易传到网络中</li><li>然后，网络上有些机器叫记账结点，它们通过比拼计算力的方式竞争记账权。这也叫“挖矿”</li><li>获得记账权的结点，会把待记账的交易进行计算打包，并向全网广播。收到新的记账包的结点会对其进行验证，验证通过后加入自己的区块</li></ol><blockquote><p>注意，整个比特币的世界是没有服务器的，这种 P2P 的去中心化网络<strong>任何人都能修改数据</strong>。为了应对这个风险，数据要能 <strong>很容易被验证是合法的没有被修改过的</strong>，而且也要是 <strong>很难被人修改的</strong></p></blockquote><blockquote><p>基于这个设计，比特币使用了两个比较大的技术：<strong>区块链技术</strong> 和 <strong>工作量证明共识机制</strong></p></blockquote><h3 id="_1-3-数据防篡改-区块链技术" tabindex="-1">1.3 数据防篡改-区块链技术 <a class="header-anchor" href="#_1-3-数据防篡改-区块链技术" aria-label="Permalink to &quot;1.3 数据防篡改-区块链技术&quot;">​</a></h3><p><strong>什么是区块链：</strong></p><p>区块链又叫 blockchain，其中有一个一个的区块，每个区块中包括着一组交易信息，然后，每一个区块都会有一个 ID（或是一个地址），这些区块通过记录前一个区块的 ID 来形成一条链</p><p><img src="'+s+'" alt=""></p><ul><li><strong>每个块的 ID 都是通过其内容生成的</strong>，所以，只要是内容有一丁点儿的变化，这个 ID 都会完全不一样</li><li>而生成 ID 的内容中还包括上一个块的 ID。于是只要上一个块的内容变了，其 ID 也要跟着变（不然就不合法了），那么后面指向这个块的 ID 也要变。这样就会形成一个连锁效应——一个块被修改，后续的所有块都要跟着一起改。于是导致了修改成本的提升</li><li>这种一处改，处处改的方式，并不代表不能篡改，而只是让修改面比较大，让你的改动麻烦一点</li><li>越旧的区块的篡改会造成越大面积的修改，于是越旧的区块就不容易篡改，就越安全。反之，越新的区块就越不安全</li></ul><h3 id="_1-4-数据放篡改-共识机制" tabindex="-1">1.4 数据放篡改-共识机制 <a class="header-anchor" href="#_1-4-数据放篡改-共识机制" aria-label="Permalink to &quot;1.4 数据放篡改-共识机制&quot;">​</a></h3><p>真正让区块链做到非常难篡改的是工作量证明的共识机制</p><p><strong>解决数据一致性相关的问题：</strong></p><ol><li><strong>以谁的数据为准。</strong> 任何结点都可以修改自己所下载的账本，也就是任何一个人都可以伪造账本。那么，谁的数据才是对的？在去中心化的网络下，我们只能认为，大多数人认识的数据是对的</li><li><strong>“大多数人”的问题。</strong> 在网络世界里，我可以用程序模拟出无穷多的“人”出来投票，所以，用人数来解决去中心化的问题，在分不清是人还是计算机</li><li><strong>意见分歧问题。</strong> 如果在同一个时刻，有多个人都在告诉其他人，这账应该这么记。而且，他们的数据都合法，那么，整个网络应该听谁的？</li></ol><blockquote><p>为了解决这几个问题，比特币使用了 <code>Proof-of-Work</code> 工作量证明机制，也就是“挖矿”。所谓的“挖矿”其实就是用大规模的计算来找到一个符合系统要求的区块 ID。要找到符合条件的区块 ID 只能通过暴力穷举的方式，所以要付出大量的系统计算资源和电力。</p></blockquote><p><strong>这种极度消耗计算力的方式有效的解决下面几个问题：</strong></p><ol><li><strong>修改几乎变得不可能。</strong> 如果生成一个区块需要大量的长时间的计算力，也就是在世界上最好的电脑集群下计算 10 分钟才能打好一个包。那么修改一个块数据就很困难，并且如果要伪造一个块，那么你就要修改后面所有的块</li><li><strong>能掌握 51% 的算力的人变得几乎不可能。</strong> 除了伪造一条链的成本很高，还要控制大多数人的算力，这意味着需要巨额的资金投入。这两个难度加起来，几乎不太可能</li><li><strong>解决分歧。</strong> 就算是出现了合法冲突的区块（同时出现了多个合理的区块，即区块链出现分支 / 分叉），也就是多个合法的账本。而因为挖矿的成本太高，导致要同时跟进多个账本是不可能的，所以矿工们只能赌跟其中一个。大多数人所选择的那一个分支的链就会越来越多，于是另外一边也就无人问津，从而作废了</li></ol><h2 id="_2-区块格式" tabindex="-1">2 区块格式 <a class="header-anchor" href="#_2-区块格式" aria-label="Permalink to &quot;2 区块格式&quot;">​</a></h2><h3 id="_2-1-区块链的协议格式" tabindex="-1">2.1 区块链的协议格式 <a class="header-anchor" href="#_2-1-区块链的协议格式" aria-label="Permalink to &quot;2.1 区块链的协议格式&quot;">​</a></h3><p>区块链就像一个单向链表，一个数据块中保存着三个信息：</p><ol><li>真正的数据</li><li>自己的地址（或是 ID）</li><li>前一个数据块的地址</li></ol><blockquote><p>数据块的地址使用哈希算法编码</p></blockquote><p><strong>下图是区块链的协议格式：</strong></p><p><img src="'+n+'" alt=""></p><ul><li><strong>区块数据协议头：</strong> <code>Version</code> <code>Previous Block Hash</code> <code>Merkle Root</code> <code>Timestamp</code> <code>Difficulty Target</code> <code>Nonce</code></li><li><strong>交易数据：</strong> 分别是：本块中的交易笔数 H 和交易列表（最多不能超过 1MB，为什么是 1MB，后面会说）</li></ul><p><strong>区块头：</strong></p><ul><li><code>Version</code>：当前区块链协议的版本号，4 个字节。如果升级了，这个版本号会变</li><li><code>Previous Block Hash</code>：前面那个区块的 hash 地址。32 个字节</li><li><code>Merkle Root</code>：这个字段可以简单理解为是后面交易信息的 hash 值 。32 个字节</li><li><code>Timestamp</code>：区块生成的时间。这个时间不能早于前面 11 个区块的中位时间，不能晚于 <code>网络协调时间</code> ——你所连接的所有结点时间的中位数。4 个字节</li><li><code>Bits</code>：也就是上图中的 Difficulty Tagrget，表明了当前的 hash 生成的难度。4 个字节</li><li><code>Nonce</code>：一个随机值，用于找到满足某个条件的 hash 值。4 字节</li></ul><blockquote><p>对这六字段进行 hash 计算，就可以得到本区块的 hash 值，也就是其 ID 或是地址</p></blockquote><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>SHA-256(SHA-256 (Block Header))</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>当然，事情并没有这么简单。比特币对这个 <code>hash</code> 值是有要求的，其要求是那个 <code>Bits</code> 字段控制的，然后你可以调整 <code>Nonce</code> 这个 32 位整型的值来找到符合条件的 <code>hash</code> 值。我们把这个事情叫做 <strong>挖矿</strong></p></blockquote><h3 id="_2-2-merkle-root" tabindex="-1">2.2 Merkle Root <a class="header-anchor" href="#_2-2-merkle-root" aria-label="Permalink to &quot;2.2 Merkle Root&quot;">​</a></h3><p><strong>比特币的 Merkle Root 是怎么计算出来的：</strong></p><ol><li>比特币的每一笔交易会有三个字段，一个是转出方，一个是转入方，还有一个是金额</li><li>对每个交易的这三个字段求 hash</li><li>然后把交易的 hash 做两两合并，再求其 hash</li><li>直到算出最后一个 hash 值，这就是我们的 <code>Merkle Root</code></li></ol><p><img src="'+p+'" alt=""></p><p>下图是一个区块链的示意图，来自比特币的白皮书：</p><p><img src="'+c+'" alt=""></p><blockquote><p>为什么要这样做呢？为什么不是把所有的交易都放在一起做一次 hash 呢？这不也可以让人无法篡改吗？这样做的好处是——我们把交易数据分成了若干个组。就像上面那个二叉树所表示的一样，我们可以不断地把这个树分成左边的分支和右边的分支，因为它们都被计算过 hash 值，所以可以很快地校验其中的内容有没有被修改过</p></blockquote><p><strong>这至少带来三个好处：</strong></p><ol><li>大量的交易数据可以被分成各种尺寸的小组，这样有利于我们整合数据和校验数据</li><li>这样的开销在存储和内存上并不大，然而我们可以提高校验一组数据的难易程度</li><li>在 P2P 的无中心化网络上，我们可以把大量数据拆成一个一个小数据片传输，可以提高网络的传输速度</li></ol><h3 id="_2-3-比特币的交易模型" tabindex="-1">2.3 比特币的交易模型 <a class="header-anchor" href="#_2-3-比特币的交易模型" aria-label="Permalink to &quot;2.3 比特币的交易模型&quot;">​</a></h3><p>比特币交易中的两个术语：</p><ul><li><p><code>input</code> 支出方</p></li><li><p><code>output</code> 收入方</p></li><li><p>一个交易可以有多个 output，也就是说我可以把一笔钱汇给多个人</p></li><li><p>output 跟 input 的总数要吻合</p></li></ul><blockquote><p><strong>UTXO：</strong> （Unspent Transaction Output）没有花出去的交易。假设，Fred 给了 Alice 2 个比特币，Ted 给了 Alice 3 个比特币，这个时候，Alice 有 5 个比特币。比特币里是没有余额的，所以，对于 Alice 来说，她只有两个没有花出去的交易，一个是 2 个比特币，一个是 3 个比特币。系统计算余额事就是计算 UTXO</p></blockquote><p>如果 Alice 想要转给 Bob 4 个比特币，她发现自己的两个交易中都不够，也不能拆开之前的那两个比特币交易，那么她只能把交易 2 和交易 3 当成 input，然后把自己和 Bob 当成 output，Bob 分得 4 个，她自己分 1 个</p><p><img src="'+h+'" alt=""></p><p>UTXO 因为没有账户和余额的概念，所以可以并行进行多笔交易。假如你有多个 UTXO，你可以进行多笔交易而不需要并行锁。然后其还有匿名性的特征，你可以隐藏自己的交易目的地（通过设置的多个 output），而且没有余额意味着是没有状态的。要知道你有多少个比特币，只需要把 UTXO 的交易记录统计一下就可以知道了</p><h2 id="_3-加密方式" tabindex="-1">3 加密方式 <a class="header-anchor" href="#_3-加密方式" aria-label="Permalink to &quot;3 加密方式&quot;">​</a></h2><h3 id="_3-1-密钥对" tabindex="-1">3.1 密钥对 <a class="header-anchor" href="#_3-1-密钥对" aria-label="Permalink to &quot;3.1 密钥对&quot;">​</a></h3><p>所谓密钥对，也就是一种非对称加密技术。在对信息进行加密和解密时，使用两个不同的密钥</p><ul><li><strong>公钥</strong>：公布出去，任何人都能看到。只能加密，解密需要私钥，信息使用公钥加密后只能用私钥解密，其他人无法解密 (可以使用公钥加密，私钥解密，也有反过来用私钥加密，公钥解密)</li><li><strong>私钥</strong>：只能自己看到。用来解密</li></ul><h3 id="_3-2-数字签名" tabindex="-1">3.2 数字签名 <a class="header-anchor" href="#_3-2-数字签名" aria-label="Permalink to &quot;3.2 数字签名&quot;">​</a></h3><p><strong>非对称加密的缺陷：</strong></p><p>每个人都有我的公钥，别人可以截获发件人发给我的信息，然后自己用我的公钥加密一个别的信息，伪装成发件人发给我，这样我就被黑了</p><p>所以，我们需要对发件人的身份进行验证，此时就需要用到 <strong>数字签名</strong> 的概念了</p><p><strong>数字签名的加密过程：</strong></p><ol><li>Mike(发件人) 也有一对密钥对，一个公钥给了 Jack，私钥自己保留</li><li>Mike(发件人) 把需要发送的信息做个 hash，得到一个 hash 串，又叫 <strong>Digest</strong></li><li>Mike(发件人) 用自己的私钥，把 Digest 加密，得到一段 Digest 的密文。我们把这个过程叫 <strong>数字签名</strong>，Signature</li><li>然后，Mike(发件人) 把需要发送的信息用我的公钥加密后，连同他的数字签名一同发给 Jack</li><li>Jack 用自己的私钥解密 Mike 发给他的密文，然后用 Mike 的公钥解密其数字签名得到 Digest</li><li>然后，对解开的密文做 Hash。如果结果和 Digest 一致，就说明，这个信息是 Mike 发送的，没有人更改过</li></ol><p><img src="'+a+'" alt=""></p><h3 id="_3-3-证书" tabindex="-1">3.3 证书 <a class="header-anchor" href="#_3-3-证书" aria-label="Permalink to &quot;3.3 证书&quot;">​</a></h3><p><strong>中间人攻击：</strong></p><ol><li>假设有个黑客偷偷地把 Jack(收件人) 电脑上的 Mike 的公钥给换了，换成自己的</li><li>然后截获 Mike 发出来的信息，用自己的密钥加密一段自己的信息，以及自己的数字签名</li><li>对于 Jack(收件人) 来看，因为他用了黑客的公钥，而不是 Mike 的</li><li>那么对他来说，他就以为信息来自 Mike，于是黑客可以用自己的私钥伪装成 Mike 给 Jack 通信</li></ol><p><strong>证书：</strong></p><ol><li>为了应对中间人攻击，需要保证自己的公钥匙不被篡改</li><li>这就需要一个权威机构来认证公钥。权威机构，用自己的私钥把 Mike(发件人) 的公钥和其相关信息一起加密，生成一个 <strong>证书</strong></li><li>Mike(发件人) 只需要在发送信息的时候放上这个权威机构发的数字证书</li><li>然后 Jack(收件人) 用这个 <code>权威机构的公钥</code> 解密这个证书，得到 Mike 的公钥</li><li>再用 Mike 的公钥来验证 Mike 的数字签名</li></ol><h2 id="_4-比特币的加密" tabindex="-1">4 比特币的加密 <a class="header-anchor" href="#_4-比特币的加密" aria-label="Permalink to &quot;4 比特币的加密&quot;">​</a></h2><p>在比特币中，每一笔交易的 From 和 To 都是每个用户的公钥（Public Key）。也就是说，使用用户的公钥来做交易的账户</p><p>交易的发起方只能是支付方，支付方需要用自己的私钥来加密交易信息并制作相关的交易签名</p><p>网络上其他人会用支付方的公钥（也就是交易的支出方）来做解密来验证</p><blockquote><p>为什么不需要那个证书机构呢？不怕中间人攻击吗？这是因为，如果黑客想要伪造一笔别人的交易，那么他需要换掉半数以上结点上的被攻击者的公钥，这不太现实</p></blockquote><p>下面是一个交易链的图示。这个交易链的钱从 A -&gt; B -&gt; C -&gt; D，一共 3 笔交易：</p><p><img src="'+l+'" alt=""></p><ul><li><strong>发起交易</strong>：我们从第一笔交易可以看到，A 用自己的私钥为交易信息和自己的地址生成了交易的签名，然后把交易信息、自己的地址、交易签名和自己的公钥放出去，这样方便别人来验证的确是 A 发起的</li><li><strong>验证交易</strong>：在验证时，使用 A 的公钥解密交易签名，得到交易的 hash 值。把交易信息和自己的地址做 hash，看看是不是和签名解密后的 hash 值一致</li></ul><h2 id="_5-比特币的挖矿" tabindex="-1">5 比特币的挖矿 <a class="header-anchor" href="#_5-比特币的挖矿" aria-label="Permalink to &quot;5 比特币的挖矿&quot;">​</a></h2><h3 id="_5-1-挖矿的概念" tabindex="-1">5.1 挖矿的概念 <a class="header-anchor" href="#_5-1-挖矿的概念" aria-label="Permalink to &quot;5.1 挖矿的概念&quot;">​</a></h3><p>前面说到，在比特币的区块 hash 算法中，要确保下面这个公式成立：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>SHA-256(SHA-256 (Block Header)) &lt; Target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>而在区块头中，可以完全自由修改的只有一个字段，就是 Nonce，其他的 Timestamp 可以在特定范围内修改，Merkle Root 和你需要记录的交易信息有关系 <strong>所有的矿工可以自由地从待确认交易列表中挑选自己想要的交易打包</strong></p><blockquote><p>Target 是一个数，表示计算出来的 hash 值的字符串最前面有几个零。我们把这个操作叫“哈希碰撞”(hash collision)，碰撞前几个位都是 0 的哈希值。这个 Target 是由区块头中的 Bits 这个字段控制的，也就是难度系数</p></blockquote><p>这个难度系数，会在每出 2016 个区块后就调整一次。现在，这个难度是要在前面找到有 18 个零。如下所示 (一个真实的区块链的 Hash 值)：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>000000000000000000424118cc80622cb26c07b69fbe2bdafe57fea7d5f59d68</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><blockquote><p>很有可能穷举完 Nonce 后还找不到，那就只能调整 Timestamp 和 Merkle Root（调整不同的记账交易）了</p></blockquote><h3 id="_5-2-挖矿的流程" tabindex="-1">5.2 挖矿的流程 <a class="header-anchor" href="#_5-2-挖矿的流程" aria-label="Permalink to &quot;5.2 挖矿的流程&quot;">​</a></h3><p><strong>一般的挖矿流程如下：</strong></p><ol><li>从网络上取得之前的区块信息</li><li>从 <code>待记账区</code> 中获取一组交易数据（有优先级，比如成长时间、矿工小费等）</li><li>形成区块头（计算 <code>Merkle Root</code> 并设计记账时间 <code>Timestamp</code> 等）</li><li>开始穷举 <code>Nonce</code>，来计算区块头的 <code>hash</code> 值。如果前面有 18 个零（小于 Target），那么记账成功。如果没有，则从第一步重新开始</li><li>一旦某矿工成功打包一个区块，他就会告诉其他矿工。收到消息的矿工会停下手上的工作，开始验证，验证通过后，广播给其他矿工</li></ol><p>设置这个难度系数就是为了让全网产生的区域名平均在 10 分钟一块。而根据比特币无中心服务器的架构，也就是其挖矿的机器数量是想来就来想走就走的，计算力可能会不一样。因此，为了保证每 10 分钟产生一个区块，当算力不足的时候，难度下降，当算力充足的时候，难度提高</p><h2 id="_6-共识机制" tabindex="-1">6 共识机制 <a class="header-anchor" href="#_6-共识机制" aria-label="Permalink to &quot;6 共识机制&quot;">​</a></h2><h3 id="_6-1-拜占庭问题" tabindex="-1">6.1 拜占庭问题 <a class="header-anchor" href="#_6-1-拜占庭问题" aria-label="Permalink to &quot;6.1 拜占庭问题&quot;">​</a></h3><p>拜占庭将军问题（The Byzantine Generals Problem），它是莱斯利·兰伯特（Leslie Lamport）于 1982 年提出来的，用来解释一致性问题的一个虚构模型。同时，它也是分布式领域中最复杂、最严格的容错模型</p><p>无论你是搞区块链，还是搞分布式，你都需要知道拜占庭容错系统研究中的三个重要理论：CAP、FLP 和 DLS</p><ul><li><strong>CAP</strong>：在网络发生阻断（partition）时，只能选择数据的一致性（consistency）或可用性（availability），无法两者兼得</li><li><strong>FLP</strong>：在异步环境中，如果节点间的网络延迟没有上限，只要有一个恶意节点存在，就没有算法能在有限的时间内达成共识</li><li><strong>DLS</strong>：容错的上限： <ul><li>在部分同步的网络环境中（即网络延迟有一定的上限，但我们无法事先知道上限是多少），协议可以容忍最多 1/3 的拜占庭故障</li><li>在异步网络环境中，具确定性质的协议无法容忍任何错误</li><li>在同步网络环境中（网络延迟有上限且上限是已知的），协议可以容忍 100% 的拜占庭故障。但当超过 1/2 的节点为恶意节点时，会有一些限制条件</li></ul></li></ul><h3 id="_6-2-分布式一致性算法" tabindex="-1">6.2 分布式一致性算法 <a class="header-anchor" href="#_6-2-分布式一致性算法" aria-label="Permalink to &quot;6.2 分布式一致性算法&quot;">​</a></h3><ul><li><strong>PoW</strong>：Proof of Work，比特币的区块链网络使用 PoW</li></ul><h3 id="_6-3-pow-工作量证明" tabindex="-1">6.3 Pow 工作量证明 <a class="header-anchor" href="#_6-3-pow-工作量证明" aria-label="Permalink to &quot;6.3 Pow 工作量证明&quot;">​</a></h3><p><strong>概念：</strong></p><p>比特币的挖矿算法并不是比特币开创的，其原型叫 Hashcash，一开始这个算法是用来限制垃圾邮件的。Hashcash 一开始要求邮件发送方对邮件头（其中包括时间和收件人地址）计算一个 160bit 的 SHA-1 哈希值。其前面需要有 5 个零，也就是 20bit 的 0</p><p>为什么要设计成这个样子？因为如果我们发正常邮件，这点算力对于发送方来说，没有什么。但对于需要大量发送垃圾邮件的人来说，这就是一个很大的成本了。那些控制着用户的僵尸网络的黑客来说，发送垃圾邮件时，导致 CPU 使用率过高，会马上引起电脑所有者的警觉，而且还很容易定位相应的恶意程序</p><p><strong>工作量证明的作用：</strong></p><ul><li><strong>提高对数据篡改的成本</strong>：让你修改数据需要付出大量的算力，而区块链的数据相互依赖，导致一处改处处改，因此你要完全修改就需要付出大量的算力</li><li><strong>提高网络中有不同声音的成本</strong>：如果一个网络有不同的人给出来了不同的账本而且都合法，那么就无法确定需要相信谁。所以挖矿可以解决这个问题，让你要做一个伪造账本的成本极其地大，而校验账本的成本很小</li><li><strong>解决分歧</strong>：当有不同声音的时候，即区块链出现分叉时，所有的矿工只能选择其中一个分支（因为没人有算力可以同时发出两个不同的声音)。于是，大多数人选择的那个分支就会成为事实，少数人选的那头就被遗忘了。这让整个去中心化系统的一致性，不再以人数多认可的数据为准，而是以算力多的人认可的数据为准</li></ul><p>比特币的区块链网络在设计时使用的 PoW（Proof of Work） 算法思路。一个是限制一段时间内整个网络中出现提案的个数（增加提案成本），另外一个是放宽对最终一致性确认的需求，约定好大家都确认并沿着已知最长的链进行拓宽。</p><p>也就是说，如果比特币系统在某一个时刻同时出现了两个都合法的区块，那么两个都承认。于是，区块链上会出现两个合法的分支（术语叫 &quot;分叉&quot;）。此时矿工可以选择任何一个分支继续，在某个分支的长度超过了另一个分支时，短的那个分支马上作废</p><p>当然，PoW 的初衷是通过消耗资源的方式来阻止一些恶意攻击。然而在区块链的去中心化的世界里，PoW 还有另一个功能，那就是让这些不受控制的分布式 P2P 网络里的结点统一思想。也就是说我们常说的，分布式一致性。这对分布式系统中的交易系统来说是一件非常重要的事</p><h3 id="_6-4-pos-股权证明协议" tabindex="-1">6.4 PoS 股权证明协议 <a class="header-anchor" href="#_6-4-pos-股权证明协议" aria-label="Permalink to &quot;6.4 PoS 股权证明协议&quot;">​</a></h3><p><strong>背景：</strong></p><p>PoW 耗费的电力和时间成本是越来越大了。所以，为了每个 Block 更快的生成，出现了 PoS （Proof of Stake）协议，中文翻译为股权证明协议</p><p><strong>概念：</strong></p><ul><li>在 PoS 机制下，矿工不在叫矿工，而是叫 Validator（校验者）</li><li>假设现在有一个区域需要被生成，而现在有 4 个 Validator，每一个 Validator 需要以 &quot;交押金&quot; 的方式来取得记账权</li><li>假如，A 交的押金占了 38%，B 占 25%，C 点 21%，D 占 16%。那么，他们按照股权的比权来获得记账权</li><li>比如，A 有 38% 的概率可以获得记账权（不是由系统随机分配，还是要算 hash 值，只不过是财富越多的人挖矿的难度越小）</li><li>而如果你发起恶意攻击的话，你的钱就会被系统没收充公。Validator 记账后没有奖金，只有手续费</li></ul><blockquote><p>也就是说，在 PoS 机制下，记账权不再像 PoW 那样由谁的算力大谁就越有机会来记账，而是由谁的财富多，谁就越有可能来记账。于是，记账权按大家财富的比例来分配</p></blockquote><p><strong>PoS 的优势：</strong></p><ol><li>不需要那么费劲的挖矿了。PoS 很明显地解决了这个问题</li><li>在 P2P 这种无中心化的网络下，如果你要控制整个网络，就需要超过半数以上的能力。在 PoW 下，需要 51% 的算力。而在 PoS 下，你需要有 51% 的财富，你才可以发起攻击</li></ol><p><strong>PoS 潜在的问题：</strong></p><p>当不需要太多算力的时候，如果账本出现分叉的情况，也就是系统出现两个冲突且合法的区块的时候，在比特币这种算力密集的 PoW 机制下，所有的矿工必需赌其中一个分支往下走。因为算力的问题，所以基本上来说不太可能同时在两个分支上发展。而其中一个分支如果长于另一个分支，较短的那个分支就会被孤立出去，其上的账本就都不作数了，而矿工的奖励也没有了。这是 PoW 机制的好处</p><p>而在 PoS 这种不需要算力的机制下，就可以让记账人们在两个分支上同时进行，以争取实现利益的最大化（无论哪个分支最终胜出，我都可以有利）。这样一来，攻击者就可以利用这种情况来发起 Nothin-At-Stake 攻击。</p><p>也就是说，如果绝大多数人都在发展两个分支，假设有 99% 的人发展 A 分支，99% 的人也同时发展 B 分支，而有 1% 股份的人在分支 A 中写一笔交易，然后在 B 分支没有这笔交易，当其在 A 分支上达成合约后（比如，收到商品），加入 B 分支，然后 B 分支胜出，导致其没有交易</p><h3 id="_6-5-dpos-委托股权证明" tabindex="-1">6.5 DPoS 委托股权证明 <a class="header-anchor" href="#_6-5-dpos-委托股权证明" aria-label="Permalink to &quot;6.5 DPoS 委托股权证明&quot;">​</a></h3><p>PoS 的问题也很多，所以有人又提出来了一个进化版，叫 DPoS（Delegated Proof of Stake，委托股权证明）</p><p>在常规 PoW 和 PoS 中，一大影响效率之处在于任何一个新加入的区块，都需要被整个网络所有节点做确认。DPoS 优化方案在于：通过不同的策略，不定时地选中一小群节点，这一小群节点做新区块的创建、验证、签名和相互监督。这样就大幅度减少了区块创建和确认所需要消耗的时间和算力成本。</p><p>DPoS 下每个 token 都是选票，大家票选 20 个选举人团 +1 个随机选举人 =21 个选举人代表网络。然后每隔一段时间，在这 21 个人中挑选一个出来维护账本并获得收益</p><h2 id="_7-智能合约" tabindex="-1">7 智能合约 <a class="header-anchor" href="#_7-智能合约" aria-label="Permalink to &quot;7 智能合约&quot;">​</a></h2><h3 id="_7-1-以太坊的智能合约" tabindex="-1">7.1 以太坊的智能合约 <a class="header-anchor" href="#_7-1-以太坊的智能合约" aria-label="Permalink to &quot;7.1 以太坊的智能合约&quot;">​</a></h3><p>对于以太坊来说，智能合约其实就是一段可执行的程序片段，由发布人使用一种类似于 JavaScript 或是 Python 的编程语言来编写</p><p>我们把合约代码在本地编译成功后发布到区块链上，可以理解为一个特殊的交易（包括可执行代码），然后会被矿工打包记录在某一个区块中。当需要调用这个智能合约的方法时，只需要向这个智能合约的地址发送一笔交易即可。</p><p>每个节点的电脑都需要安装以太坊客户端，客户端自带了一个和 JVM 类似的一个 EVM。通过交易触发智能合约后，智能合约的代码就会在 EVM 中执行了。这种方式相当于把程序部署到了非常非常多的电脑上，随时都可以通过交易来触发这些智能合约的执行，也从而完成了分布式程序的部署和调用</p><h3 id="_7-2-合同的-bug" tabindex="-1">7.2 合同的 Bug <a class="header-anchor" href="#_7-2-合同的-bug" aria-label="Permalink to &quot;7.2 合同的 Bug&quot;">​</a></h3><p>有程序的地方就会有 Bug，现实生活中会有 Bug，合同也会有 Bug。出现了 Bug 后，大家可以相互协商，给合同打补丁（附加条款，或是重新签合同）。然而，代码合同则不一样，Bug 也会被残酷无情地执行，一旦执行就很难补救了</p><p><strong>案例 The DAO：</strong></p><p>最著名的例子就是以太坊一个叫 The DAO 的应用，它是一个去中心化的风险投资基金，以智能合约的形式运行在以太坊区块链上。它也是一个盈利性的去中心化自治组织，它将利用自己掌控的以太币资金通过投资以太坊上的应用为其成员创造价值。在 The DAO 创建期，任何人都可以向它的众筹合约发送以太币，获得 DAO 代币。</p><p>因为 The DAO 这个程序写得不好，黑客在其智能合约里找到 Bug，把所有的钱给调走了，大约 7000 多万美刀。这成为有史以来最大宗的数字劫案，而且 FBI 也找不到人。这个项目因为钱被偷走而倒闭以后，引起了以太坊的强行分叉，变成 ETH 和 ETC</p><p><strong>案例 Parity 被盗：</strong></p><p>还有一个案例，是 2017 年发生的智能钱包（多签名钱包）Parity 被盗事件。它号称自己的智能合约被很多很厉害的安全人员都审查过，都认为没问题。但最后还是被黑客利用了一个叫做 initwallet 的函数，反复调用它，转走了 3000 万美金</p>',130)])])}const x=e(d,[["render",g]]);export{f as __pageData,x as default};
